/* A growing curriculum map: reading, self-checks and quiz evidence stay distinct. */
const knowledgeDraftTopics=new Map(),knowledgeDraftCases=new Map();
let knowledgeMapFilter={stage:'all',session:'all',state:'all',query:''};
const knowledgeTopicKey=id=>'wset3-map-topic-'+id;
const knowledgeCaseKey=id=>'wset3-map-case-'+id;
function knowledgeRecord(key,fallback){const v=read(key,null);return v&&typeof v==='object'&&!Array.isArray(v)?v:fallback}
function knowledgeTopicRecord(id){const r=knowledgeDraftTopics.get(id)||knowledgeRecord(knowledgeTopicKey(id),{});return {answer:typeof r.answer==='string'?r.answer:'',checks:r.checks&&typeof r.checks==='object'?r.checks:{},verified:r.verified===true,fingerprint:r.fingerprint||'',savedAt:r.savedAt||null}}
function knowledgeTopicFingerprint(record){return JSON.stringify([record.answer,...['explain','compare','apply'].map(id=>record.checks[id]===true)])}
function knowledgeTopicState(id,record=knowledgeTopicRecord(id)){const all=record.answer.trim()&&['explain','compare','apply'].every(id=>record.checks[id]===true);return record.verified&&all&&record.fingerprint===knowledgeTopicFingerprint(record)?'checked':record.answer.trim()||Object.values(record.checks).some(Boolean)?'working':'unassessed'}
function saveKnowledgeTopic(id,record,verify=false){if(!knowledgeTopics.some(t=>t.id===id)||!record||typeof record.answer!=='string'||!record.checks)return false;const clean={answer:record.answer,checks:Object.fromEntries(['explain','compare','apply'].map(k=>[k,record.checks[k]===true])),verified:false,savedAt:Date.now()};clean.verified=!!(verify&&clean.answer.trim()&&Object.values(clean.checks).every(Boolean));clean.fingerprint=knowledgeTopicFingerprint(clean);const ok=save(knowledgeTopicKey(id),clean);if(ok)knowledgeDraftTopics.delete(id);else knowledgeDraftTopics.set(id,{...clean,verified:false});return ok}
function knowledgeIsRead(topic){const a=read(topic.session===1?'wset3-completed':'wset3-session'+topic.session+'-completed',[]);return Array.isArray(a)&&a.includes(topic.unit)}
function knowledgeTopicHref(topic){return topic.href||(topic.session===1?'#lesson/'+topic.unit:'#session'+topic.session+'/'+topic.unit)}
function knowledgeQuizEvidence(topic){const linked=topic.quiz?(Array.isArray(topic.quiz)?topic.quiz:[topic.quiz]):[];let answered=0,correct=0,wrong=0;for(const q of linked){const list=q.session===1?questions:q.session===2?s2Checks:[],answers=read(q.session===1?'wset3-answers':'wset3-session'+q.session+'-answers',{}),item=list[q.index],a=answers&&answers[q.index];if(item&&Number.isInteger(a)&&a>=0&&a<(q.session===1?item.options.length:item.o.length)){answered++;if(a===(q.session===1?item.correct:item.a))correct++;else wrong++;}}return {total:linked.length,answered,correct,wrong,href:topic.session===1?'#quiz':'#session'+topic.session+'quiz'}}
function knowledgeCaseRecord(id){const r=knowledgeDraftCases.get(id)||knowledgeRecord(knowledgeCaseKey(id),{});return {answers:r.answers&&typeof r.answers==='object'?r.answers:{},checks:r.checks&&typeof r.checks==='object'?r.checks:{},verified:r.verified===true,fingerprint:r.fingerprint||''}}
function knowledgeCaseFingerprint(item,record){return JSON.stringify(item.stages.map(s=>[typeof record.answers[s.id]==='string'?record.answers[s.id]:'',record.checks[s.id]===true]))}
function knowledgeCaseState(item,record=knowledgeCaseRecord(item.id)){const all=item.stages.every(s=>typeof record.answers[s.id]==='string'&&record.answers[s.id].trim()&&record.checks[s.id]===true);return record.verified&&all&&record.fingerprint===knowledgeCaseFingerprint(item,record)?'checked':item.stages.some(s=>record.answers[s.id]?.trim?.()||record.checks[s.id])?'working':'unassessed'}
function saveKnowledgeCase(id,record,verify=false){const item=knowledgeCases.find(c=>c.id===id);if(!item||!record?.answers||!record?.checks)return false;const clean={answers:{},checks:{},verified:false,savedAt:Date.now()};for(const s of item.stages){clean.answers[s.id]=typeof record.answers[s.id]==='string'?record.answers[s.id]:'';clean.checks[s.id]=record.checks[s.id]===true;}clean.verified=!!(verify&&item.stages.every(s=>clean.answers[s.id].trim()&&clean.checks[s.id]));clean.fingerprint=knowledgeCaseFingerprint(item,clean);const ok=save(knowledgeCaseKey(id),clean);if(ok)knowledgeDraftCases.delete(id);else knowledgeDraftCases.set(id,{...clean,verified:false});return ok}
function knowledgeGaps(){const gaps=[];for(const t of knowledgeTopics){const state=knowledgeTopicState(t.id),e=knowledgeQuizEvidence(t);if(e.wrong)gaps.push({type:'quiz',topic:t.id,text:t.title+'：关联小测有错题，先回看原因。'});if(state==='checked')for(const id of t.requires){const p=knowledgeTopics.find(x=>x.id===id);if(p&&knowledgeTopicState(id)!=='checked')gaps.push({type:'prerequisite',topic:p.id,text:'已自查「'+t.title+'」，但前面的「'+p.title+'」还未自查通过。'});}}
 for(const c of knowledgeCases)if(c.topics.every(id=>knowledgeTopicState(id)==='checked')&&knowledgeCaseState(c)!=='checked')gaps.push({type:'connection',case:c.id,text:'相关主题都已自查，接下来把「'+c.title+'」的因果链写完整。'});
 return gaps;
}
function knowledgeNext(){const gaps=knowledgeGaps(),first=gaps.find(g=>g.topic);if(first)return knowledgeTopics.find(t=>t.id===first.topic);return knowledgeTopics.find(t=>knowledgeTopicState(t.id)!=='checked'&&knowledgeIsRead(t))||knowledgeTopics.find(t=>knowledgeTopicState(t.id)!=='checked')||null}
function knowledgeStats(){return {total:knowledgeTopics.length,checked:knowledgeTopics.filter(t=>knowledgeTopicState(t.id)==='checked').length,read:knowledgeTopics.filter(knowledgeIsRead).length,cases:knowledgeCases.filter(c=>knowledgeCaseState(c)==='checked').length}}
function knowledgeStateLabel(state){return {unassessed:'待自查',working:'自查中',checked:'自查通过'}[state]}
function knowledgeTopicCard(t){const state=knowledgeTopicState(t.id),e=knowledgeQuizEvidence(t);return `<article class="km-topic" data-km-topic="${t.id}" data-status="${state}"><img class="km-topic-image" src="${t.image}" alt="${t.title}知识插画" loading="lazy"><div class="km-topic-head"><small>SESSION 0${t.session} · ${knowledgeIsRead(t)?'已读':'未标记已读'}</small><h3>${t.title}</h3></div><div class="km-topic-badges"><span class="km-status" data-status="${state}">${knowledgeStateLabel(state)}</span><span class="km-evidence ${e.wrong?'has-gap':''}">${e.wrong?'小测有错题':e.answered?'小测 '+e.correct+'/'+e.answered+' 正确':e.total?'小测未作答':'暂无关联小测'}</span></div><p class="km-topic-summary">${t.summary}</p><div class="km-dependencies">${t.requires.length?'先连起：'+t.requires.map(id=>{const p=knowledgeTopics.find(x=>x.id===id);return p?`<button type="button" data-km-focus="${id}">${p.title} ${knowledgeTopicState(id)==='checked'?'✓':'↗'}</button>`:''}).join(''):'从这里建立基础'}</div><button class="km-open" type="button" data-km-open="${t.id}">展开逻辑自查 <span>→</span></button></article>`}
function knowledgeDiagnosis(){const gaps=knowledgeGaps(),next=knowledgeNext(),unchecked=knowledgeTopics.filter(t=>knowledgeTopicState(t.id)!=='checked').length;return `<h2>下一步，补哪一段逻辑？</h2><ul class="km-gaps">${gaps.slice(0,4).map(g=>`<li>${g.topic?`<button type="button" data-km-focus="${g.topic}">${g.text}</button>`:`<a href="#case-${g.case}" data-book-jump="case-${g.case}">${g.text}</a>`}</li>`).join('')||`<li>${unchecked?'还有 '+unchecked+' 个主题待完成自查。已读之后，试着关掉材料讲一遍原因。':'所有已收录主题的单点自查已完成，再检查跨主题情境的解释是否连贯。'}</li>`}</ul>${next?`<button class="km-next" type="button" data-km-focus="${next.id}">继续检查：${next.title} →</button>`:`<p class="fine">自查记录反映你的判断；隔一段时间不看材料再解释一次，更能暴露记忆与逻辑的缺口。</p>`}`}
function knowledgeCaseCard(item){const record=knowledgeCaseRecord(item.id),state=knowledgeCaseState(item,record);return `<details class="km-case" id="case-${item.id}" data-km-case="${item.id}"><summary><strong>${item.title}</strong><span data-km-case-label>${knowledgeStateLabel(state)}</span></summary><div class="km-case-body"><img class="km-case-image" src="${item.image}" alt="${item.title}情境插画" loading="lazy"><p>${item.context}</p><p class="fine">把四步写全，再按提示检查。答案用于自查，不自动评分。</p>${item.stages.map(s=>`<label class="km-case-field"><span>${s.label}</span><small>${s.prompt}</small><textarea data-km-case-answer="${s.id}" aria-label="${item.title} · ${s.label}" placeholder="写下这一环怎样影响下一环…">${safe(typeof record.answers[s.id]==='string'?record.answers[s.id]:'')}</textarea></label><details class="km-hint"><summary>检查这一环的思路</summary><p>${s.hint}</p></details>`).join('')}<div class="km-case-check">${item.stages.map(s=>`<label><input type="checkbox" data-km-case-check="${s.id}" ${record.checks[s.id]?'checked':''}>我能解释${s.label}这一环，并说清条件</label>`).join('')}</div><p class="km-pitfall">避免：${item.pitfalls.join('；')}。</p><button class="primary km-case-save" type="button" data-km-case-save>保存本次自查</button><p class="km-case-status" role="status">${state==='checked'?'四步推理已自查通过。':'写完四步并逐项确认后，才能记为这条推理自查通过。'}</p><div class="km-detail-links">${item.topics.map(id=>{const t=knowledgeTopics.find(t=>t.id===id);return t?`<button type="button" data-km-focus="${id}">${t.title} ↗</button>`:''}).join('')}</div></div></details>`}
function knowledgeGroups(){const labels={conditions:['自然条件','先判断葡萄园拥有多少光、热、水与养分。'],vine:['葡萄藤与果实','再看品种、结构、生理和年度变化。'],management:['管理选择','把环境与目标转成具体操作和取舍，目前收录葡萄园管理。'],wine:['酒的表现与品鉴','把酿造与陈年、结构与香气、品质和风格连接起来。']};return [...new Set(knowledgeTopics.map(t=>t.stage))].map(stage=>[stage,...(labels[stage]||[stage,'把这一组主题接回因果主线。'])])}
function knowledgeMapView(){const stats=knowledgeStats();return `<main id="main" class="wrap km-page"><header class="km-header"><div class="eyebrow">SEE THE CONNECTIONS</div><h1 class="page-title">看懂联系，才算读懂知识。</h1><p>沿着四个问题走一遍：条件是什么，葡萄怎样变化，人为什么这样做，杯中的酒会怎样？</p></header><div class="km-stats"><div class="km-stat"><strong>${stats.total}</strong><span>已收录主题</span><small>${stats.read} 个已标记阅读 · 随课程继续增加</small></div><div class="km-stat"><strong data-km-topic-count>${stats.checked} / ${stats.total}</strong><span>主题自查通过</span><small>解释原因、比较选择、应用情境 · 自评</small></div><div class="km-stat"><strong data-km-case-count>${stats.cases} / ${knowledgeCases.length}</strong><span>跨主题推理自查通过</span><small>把独立知识连成完整解释 · 自评</small></div></div><section class="km-flow"><div class="eyebrow">THE LOGIC OF WINE</div><h2>一张图，四个连续的问题。</h2><div class="km-stages"><button type="button" class="km-stage" data-km-stage="conditions"><div class="km-stage-art"><img src="assets/climate-editorial.webp" alt="山坡、日照和水体共同影响葡萄园"></div><span class="km-stage-num">01 · 自然条件</span><h3>它在哪里生长？</h3><p>气候、天气、地形、土壤<br>决定光、热、水与养分</p></button><button type="button" class="km-stage" data-km-stage="vine"><div class="km-stage-art"><img src="assets/cycle-editorial.webp" alt="葡萄藤从萌芽到成熟的年度变化"></div><span class="km-stage-num">02 · 葡萄藤与果实</span><h3>葡萄会怎样变化？</h3><p>生长、健康、负载与成熟<br>改变糖、酸、风味与单宁</p></button><button type="button" class="km-stage" data-km-stage="management"><div class="km-stage-art"><img src="assets/session2-management.webp" alt="冬剪和夏季冠层的管理选择"></div><span class="km-stage-num">03 · 管理选择</span><h3>种植者为什么这样做？</h3><p>整枝、修剪、冠层与采收<br>回应环境、目标与成本</p></button><button type="button" class="km-stage" data-km-stage="connections"><div class="km-stage-art">${knowledgeGlass()}</div><span class="km-stage-num">04 · 酒的表现</span><h3>最终带来什么结果？</h3><p>风格、品质潜力与成本<br>用情境练习连起前三步</p></button></div><p class="km-loop-note">↶ 管理也会反过来改变受光、供水、长势与健康。最后的酒还受酿造和陈年影响，后续课程会接入这条主线。</p><p class="fine">点击前三幅图筛选主题，点击第四幅图练习完整因果链。已读、小测和自查分别记录，自查通过不等于考试掌握保证。</p></section><section class="km-diagnosis" aria-label="复习建议">${knowledgeDiagnosis()}</section><section class="km-library"><div class="km-toolbar"><input class="km-search" type="search" aria-label="搜索知识主题" placeholder="搜索主题、术语或关键词…" value="${safe(knowledgeMapFilter.query)}"><select class="km-session-filter" aria-label="按课程筛选"><option value="all">全部课程</option>${[...new Set(knowledgeTopics.map(t=>t.session))].map(n=>`<option value="${n}" ${knowledgeMapFilter.session===String(n)?'selected':''}>Session ${n}</option>`).join('')}</select><select class="km-state-filter" aria-label="按自查状态筛选"><option value="all">全部自查状态</option>${[['unassessed','待自查'],['working','自查中'],['checked','自查通过'],['gaps','小测有错题或前置待查']].map(([v,t])=>`<option value="${v}" ${knowledgeMapFilter.state===v?'selected':''}>${t}</option>`).join('')}</select><button class="km-filter-clear" type="button" data-km-reset>显示全部主题</button></div><p class="km-results" aria-live="polite"></p><div class="km-topic-groups">${knowledgeGroups().map(([stage,title,desc])=>`<section class="km-group" data-group="${stage}"><h2>${title}</h2><p>${desc}</p><div class="km-topics">${knowledgeTopics.filter(t=>t.stage===stage).map(knowledgeTopicCard).join('')}</div></section>`).join('')}</div><p class="km-empty" hidden>没有匹配的主题，试试其他关键词或显示全部主题。</p></section><section id="knowledge-connections" class="km-connections"><div class="eyebrow">TEST THE CONNECTIONS</div><h2>单个知识点会了，能连起来吗？</h2><p>不看材料，先写出完整解释，再展开提示检查。这些情境会同时用到多堂课的知识。</p><div class="km-cases">${knowledgeCases.map(knowledgeCaseCard).join('')}</div></section><section class="km-roadmap"><div class="eyebrow">A GROWING MAP</div><h2>之后的课程，接到哪里？</h2><div class="km-future">${knowledgeFuture.map(f=>`<article><small>尚未加入</small><h3>${f.title}</h3><p>${f.summary}</p></article>`).join('')}</div><p class="fine">这些是后续学习方向，尚未收录，也不计入当前自查进度。学习记录仅保存在当前浏览器。</p></section><dialog class="km-detail-dialog" id="knowledge-dialog" aria-labelledby="knowledge-dialog-title"><div class="km-dialog-top"><h2 id="knowledge-dialog-title"></h2><button type="button" data-km-close aria-label="关闭知识自查">×</button></div><div class="km-dialog-body"></div></dialog></main>`}
function knowledgeGlass(){return `<svg viewBox="0 0 240 150" role="img" aria-label="酒杯图解：酸度、酒精、风味和结构共同构成酒的表现"><g fill="none" stroke="#743d49" stroke-width="2"><path d="M88 20h64l-5 46c-3 20-16 28-27 28s-24-8-27-28z" fill="#f9f4e9"/><path d="M94 60h52l-1 8c-3 17-14 24-25 24s-22-7-25-24z" fill="#b57883" stroke="none"/><path d="M120 94v33m-24 2h48"/><path d="M32 40h43m91 0h42M28 90h43m98 0h43" stroke="#a0aa85" stroke-dasharray="3 3"/></g><g font-family="sans-serif" font-size="12" fill="#586246"><text x="28" y="31">酸度</text><text x="177" y="31">酒精</text><text x="25" y="112">风味</text><text x="177" y="112">结构</text></g></svg>`}
function applyKnowledgeFilters(){let count=0;for(const card of document.querySelectorAll('[data-km-topic]')){const t=knowledgeTopics.find(t=>t.id===card.dataset.kmTopic),state=knowledgeTopicState(t.id),gaps=knowledgeQuizEvidence(t).wrong||t.requires.some(id=>knowledgeTopicState(id)!=='checked');const text=[t.title,t.summary,...t.checks.map(c=>c.question)].join(' ').toLowerCase();card.hidden=!((knowledgeMapFilter.stage==='all'||knowledgeMapFilter.stage===t.stage)&&(knowledgeMapFilter.session==='all'||Number(knowledgeMapFilter.session)===t.session)&&(knowledgeMapFilter.state==='all'||knowledgeMapFilter.state===state||knowledgeMapFilter.state==='gaps'&&gaps)&&text.includes(knowledgeMapFilter.query.trim().toLowerCase()));if(!card.hidden)count++;}for(const group of document.querySelectorAll('.km-group'))group.hidden=![...group.querySelectorAll('[data-km-topic]')].some(c=>!c.hidden);const empty=document.querySelector('.km-empty');if(empty)empty.hidden=count>0;const result=document.querySelector('.km-results');if(result)result.textContent=`显示 ${count} / ${knowledgeTopics.length} 个主题${knowledgeMapFilter.stage!=='all'?' · 已按上方逻辑环节筛选':''}`;for(const button of document.querySelectorAll('[data-km-stage]')){const selected=button.dataset.kmStage===knowledgeMapFilter.stage;button.classList.toggle('is-selected',selected);button.setAttribute('aria-pressed',String(selected));}}
function openKnowledgeTopic(id){const t=knowledgeTopics.find(t=>t.id===id);if(!t)return;const dialog=document.querySelector('#knowledge-dialog'),r=knowledgeTopicRecord(id),e=knowledgeQuizEvidence(t);dialog.dataset.topic=id;dialog.querySelector('h2').textContent=t.title;dialog.querySelector('.km-dialog-body').innerHTML=`<p class="km-detail-summary">${t.summary}</p><p class="fine">先不看材料回答三个问题，再勾选你确实能做到的项目。自查由你确认。</p><fieldset class="km-selfcheck"><legend>三个维度，检查理解</legend>${t.checks.map(c=>`<div class="km-check-row"><label><input type="checkbox" data-km-check="${c.id}" ${r.checks[c.id]?'checked':''}>${c.label}</label><p>${c.question}</p><details><summary>写完后再看提示</summary><p>${c.hint}</p></details></div>`).join('')}</fieldset><label class="km-answer"><span>用自己的话，把三个问题讲清楚</span><textarea data-km-answer placeholder="可以分三段写：原因、比较、情境应用。">${safe(r.answer)}</textarea></label><p class="km-evidence-note">阅读：${knowledgeIsRead(t)?'已标记已读':'未标记已读'} · ${e.total?(e.answered?'关联小测 '+e.correct+'/'+e.answered+' 正确':'关联小测尚无作答记录'):'本单元暂无关联选择题'}${e.wrong?'。有错题，请回看原因后再检查自己的解释。':''}</p>${t.requires.length?`<p class="fine">关联基础：${t.requires.map(id=>knowledgeTopics.find(t=>t.id===id)?.title||id).join('、')}。前面的逻辑也需要能说清。</p>`:''}<div class="km-detail-links"><a href="${knowledgeTopicHref(t)}">回到阅读单元 ↗</a><a href="${e.href}">进入本课自测 ↗</a></div><div class="km-dialog-actions"><button type="button" class="primary" data-km-save>保存本次自查</button><button type="button" data-km-close>返回地图</button><p class="km-detail-status" role="status">${knowledgeTopicState(id)==='checked'?'已自查通过，可以随时修改。':'写下解释并确认三项能力后，保存为自查通过。'}</p></div>`;
 const collect=()=>({answer:dialog.querySelector('[data-km-answer]').value,checks:Object.fromEntries([...dialog.querySelectorAll('[data-km-check]')].map(el=>[el.dataset.kmCheck,el.checked]))});
 const persist=verify=>{const ok=saveKnowledgeTopic(id,collect(),verify),status=dialog.querySelector('.km-detail-status');status.dataset.state=ok?'saved':'error';status.textContent=ok?(verify?(knowledgeTopicState(id)==='checked'?'本次自查已通过并保存。':'草稿已保存；请写下解释，并确认三个维度后再保存。'):'草稿已保存；修改后的内容需要重新确认自查。'):'保存失败，草稿暂存在本页；请复制当前解释备份后重试。';return ok};
 dialog.querySelector('[data-km-answer]').addEventListener('input',()=>{for(const el of dialog.querySelectorAll('[data-km-check]'))el.checked=false;persist(false)});for(const el of dialog.querySelectorAll('[data-km-check]'))el.addEventListener('change',()=>persist(false));dialog.querySelector('[data-km-save]').addEventListener('click',()=>persist(true));for(const button of dialog.querySelector('.km-dialog-body').querySelectorAll('[data-km-close]'))button.addEventListener('click',()=>dialog.close());dialog.showModal();}
function bindKnowledgeMap(){if(location.hash.split('/')[0]!=='#map')return;
 const dialog=document.querySelector('#knowledge-dialog');if(!dialog)return;
 const focusButtons=()=>{for(const button of document.querySelectorAll('[data-km-focus],[data-km-open]'))button.addEventListener('click',()=>openKnowledgeTopic(button.dataset.kmFocus||button.dataset.kmOpen));};focusButtons();
 dialog.querySelector('[data-km-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{if(location.hash.split('/')[0]!=='#map')return;const id=dialog.dataset.topic,y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-km-open="${id}"]`)?.focus({preventScroll:true});});
 for(const button of document.querySelectorAll('[data-km-stage]'))button.addEventListener('click',()=>{if(button.dataset.kmStage==='connections'){document.getElementById('knowledge-connections').scrollIntoView({behavior:'smooth',block:'start'});return;}knowledgeMapFilter.stage=knowledgeMapFilter.stage===button.dataset.kmStage?'all':button.dataset.kmStage;applyKnowledgeFilters();document.querySelector('.km-library').scrollIntoView({behavior:'smooth',block:'start'});});
 document.querySelector('.km-search').addEventListener('input',e=>{knowledgeMapFilter.query=e.target.value;applyKnowledgeFilters()});document.querySelector('.km-session-filter').addEventListener('change',e=>{knowledgeMapFilter.session=e.target.value;applyKnowledgeFilters()});document.querySelector('.km-state-filter').addEventListener('change',e=>{knowledgeMapFilter.state=e.target.value;applyKnowledgeFilters()});document.querySelector('[data-km-reset]').addEventListener('click',()=>{knowledgeMapFilter={stage:'all',session:'all',state:'all',query:''};document.querySelector('.km-search').value='';document.querySelector('.km-session-filter').value='all';document.querySelector('.km-state-filter').value='all';applyKnowledgeFilters()});
 for(const container of document.querySelectorAll('[data-km-case]')){const id=container.dataset.kmCase,item=knowledgeCases.find(c=>c.id===id),collect=()=>({answers:Object.fromEntries([...container.querySelectorAll('[data-km-case-answer]')].map(el=>[el.dataset.kmCaseAnswer,el.value])),checks:Object.fromEntries([...container.querySelectorAll('[data-km-case-check]')].map(el=>[el.dataset.kmCaseCheck,el.checked]))});const persist=verify=>{const ok=saveKnowledgeCase(id,collect(),verify),status=container.querySelector('.km-case-status');status.dataset.state=ok?'saved':'error';status.textContent=ok?(verify?(knowledgeCaseState(item)==='checked'?'这条四步推理已自查通过并保存。':'草稿已保存；请写完四步并逐项检查。'):'草稿已保存；修改后请重新确认推理。'):'保存失败，草稿暂存在本页，请复制备份后重试。';container.querySelector('[data-km-case-label]').textContent=knowledgeStateLabel(knowledgeCaseState(item));document.querySelector('[data-km-case-count]').textContent=knowledgeStats().cases+' / '+knowledgeCases.length;const diagnosis=document.querySelector('.km-diagnosis');diagnosis.innerHTML=knowledgeDiagnosis();for(const button of diagnosis.querySelectorAll('[data-km-focus]'))button.addEventListener('click',()=>openKnowledgeTopic(button.dataset.kmFocus));return ok;};for(const input of container.querySelectorAll('[data-km-case-answer]'))input.addEventListener('input',()=>{const check=container.querySelector('[data-km-case-check="'+input.dataset.kmCaseAnswer+'"]');if(check)check.checked=false;persist(false)});for(const input of container.querySelectorAll('[data-km-case-check]'))input.addEventListener('change',()=>persist(false));container.querySelector('[data-km-case-save]').addEventListener('click',()=>persist(true));}
 applyKnowledgeFilters();
}
